<script>
// ---- starfield background ----
(function(){
  const c=document.getElementById('stars'),x=c.getContext('2d');
  function size(){c.width=innerWidth;c.height=innerHeight;}
  size();addEventListener('resize',size);
  const st=Array.from({length:160},()=>({x:Math.random(),y:Math.random(),r:Math.random()*1.4+.2,tw:Math.random()*6}));
  (function loop(t){
    x.clearRect(0,0,c.width,c.height);
    for(const s of st){
      const a=.4+.6*Math.abs(Math.sin(t/900+s.tw));
      x.globalAlpha=a;x.fillStyle='#cdd8ff';
      x.beginPath();x.arc(s.x*c.width,s.y*c.height,s.r,0,7);x.fill();
    }
    requestAnimationFrame(loop);
  })(0);
})();

// ---- light curve chart (3 views) ----
(function(){
  const c=document.getElementById('lc');
  const ctx=c.getContext('2d');
  function fit(){c.width=c.clientWidth*devicePixelRatio;c.height=240*devicePixelRatio;ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);}
  let view='clean';
  // build synthetic data
  const N=900, per=120, depth=0.012, dur=10;
  function flux(i,mode){
    let f=1;
    if(mode!=='fold'){
      f+= (mode==='raw'? Math.sin(i/70)*0.006 + Math.sin(i/23)*0.003 : 0); // drift on raw
      const ph=((i% per)+per)%per;
      if(Math.abs(ph-per/2)<dur/2) f-=depth*(1-Math.pow((ph-per/2)/(dur/2),2));
      f+= (Math.random()-.5)*(mode==='raw'?0.006:0.0022);
    }else{
      const ph=(i/N)*per, d=Math.abs(ph-per/2);
      if(d<dur/2) f-=depth*(1-Math.pow((ph-per/2)/(dur/2),2));
      f+=(Math.random()-.5)*0.0016;
    }
    return f;
  }
  function draw(){
    fit();
    const W=c.clientWidth,H=240,padL=48,padR=12,padT=16,padB=26;
    ctx.clearRect(0,0,W,H);
    // grid
    ctx.strokeStyle='#1a2140';ctx.lineWidth=1;ctx.fillStyle='#6b74a0';ctx.font='11px Segoe UI';
    for(let g=0;g<=4;g++){const y=padT+(H-padT-padB)*g/4;ctx.globalAlpha=.5;ctx.beginPath();ctx.moveTo(padL,y);ctx.lineTo(W-padR,y);ctx.stroke();ctx.globalAlpha=1;}
    // data
    const ys=[];for(let i=0;i<N;i++)ys.push(flux(i,view));
    const mn=Math.min(...ys)-0.001, mx=Math.max(...ys)+0.001;
    const X=i=>padL+(W-padL-padR)*i/(N-1);
    const Y=v=>padT+(H-padT-padB)*(1-(v-mn)/(mx-mn));
    // baseline
    ctx.strokeStyle='#33406e';ctx.setLineDash([4,4]);ctx.beginPath();ctx.moveTo(padL,Y(1));ctx.lineTo(W-padR,Y(1));ctx.stroke();ctx.setLineDash([]);
    // points/line
    const grad=ctx.createLinearGradient(0,0,W,0);grad.addColorStop(0,'#5b8cff');grad.addColorStop(1,'#39e0ff');
    if(view==='fold'){
      ctx.fillStyle='#7f8bc0';
      for(let i=0;i<N;i++){ctx.globalAlpha=.5;ctx.beginPath();ctx.arc(X(i),Y(ys[i]),1.4,0,7);ctx.fill();}
      ctx.globalAlpha=1;
    }else{
      ctx.strokeStyle=grad;ctx.lineWidth=1.4;ctx.beginPath();
      for(let i=0;i<N;i++){const px=X(i),py=Y(ys[i]);i?ctx.lineTo(px,py):ctx.moveTo(px,py);}ctx.stroke();
    }
    // axis labels
    ctx.fillStyle='#6b74a0';
    ctx.fillText('brightness',6,padT+8);
    ctx.fillText(view==='fold'?'orbital phase':'time (days)',W/2-30,H-6);
  }
  document.querySelectorAll('.tab').forEach(t=>t.addEventListener('click',()=>{
    document.querySelectorAll('.tab').forEach(a=>a.classList.remove('active'));
    t.classList.add('active');view=t.dataset.view;draw();
  }));
  addEventListener('resize',draw);draw();
})();

// ---- 3D-ish transit animation ----
(function(){
  const c=document.getElementById('orbit'),ctx=c.getContext('2d');
  function fit(){c.width=c.clientWidth*devicePixelRatio;c.height=240*devicePixelRatio;ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);}
  fit();addEventListener('resize',fit);
  let a=0;
  (function loop(){
    fit();
    const W=c.clientWidth,H=240,cx=W/2,cy=H/2-6;
    ctx.clearRect(0,0,W,H);
    // orbit ellipse
    const rx=W*0.34, ry=42;
    ctx.strokeStyle='#2b345e';ctx.lineWidth=1;ctx.beginPath();ctx.ellipse(cx,cy,rx,ry,0,0,7);ctx.stroke();
    // star glow
    const sg=ctx.createRadialGradient(cx,cy,4,cx,cy,46);
    sg.addColorStop(0,'#fff3c4');sg.addColorStop(.35,'#ffd166');sg.addColorStop(1,'rgba(255,180,60,0)');
    ctx.fillStyle=sg;ctx.beginPath();ctx.arc(cx,cy,46,0,7);ctx.fill();
    ctx.fillStyle='#ffcf5c';ctx.beginPath();ctx.arc(cx,cy,26,0,7);ctx.fill();
    // planet position
    const px=cx+Math.cos(a)*rx, py=cy+Math.sin(a)*ry;
    const front=Math.sin(a)>0;
    const pr=7;
    function planet(){ctx.fillStyle='#7fa8ff';ctx.beginPath();ctx.arc(px,py,pr,0,7);ctx.fill();
      ctx.fillStyle='rgba(0,0,0,.35)';ctx.beginPath();ctx.arc(px+2,py-1,pr,0,7);ctx.fill();}
    if(!front)planet();           // behind star: draw first
    // (star already drawn) — front planet drawn after so it occults
    if(front)planet();
    // shadow hint on star when transiting (planet near front-center)
    a+=0.012;requestAnimationFrame(loop);
  })();
})();
</script>
</body>
</html>
