</script>
<style>
:root{
  --bg:#04050e; --panel:#0c0f1f; --panel2:#111530; --line:#1d2445;
  --text:#e7ecff; --muted:#8b94ba; --accent:#5b8cff; --accent2:#7c5cff;
  --green:#28d094; --amber:#ffb020; --red:#ff5c7a; --cyan:#39e0ff;
}
*{box-sizing:border-box} html,body{margin:0;height:100%}
body{background:radial-gradient(1300px 800px at 80% -10%,#131a3a 0%,var(--bg) 55%);
  color:var(--text);font:14px/1.5 'Segoe UI',system-ui,sans-serif;overflow-x:hidden}
#stars{position:fixed;inset:0;z-index:0;pointer-events:none;opacity:.55}
.wrap{position:relative;z-index:1;max-width:1280px;margin:0 auto;padding:20px}
header{display:flex;align-items:center;gap:14px;margin-bottom:20px}
.logo{width:42px;height:42px;border-radius:11px;background:linear-gradient(135deg,var(--accent),var(--accent2));
  display:grid;place-items:center;font-size:22px;box-shadow:0 6px 24px #5b8cff55}
.brand b{font-size:19px}.brand span{display:block;color:var(--muted);font-size:11px;letter-spacing:2px;text-transform:uppercase}
.nav{margin-left:auto;display:flex;gap:6px}
.nav a{color:var(--muted);text-decoration:none;padding:8px 16px;border-radius:9px;font-size:14px;cursor:pointer;border:1px solid transparent}
.nav a.active{color:var(--text);background:var(--panel);border-color:var(--line)}
.nav a:hover{color:var(--text)}
.badge{margin-left:6px;padding:6px 12px;border-radius:20px;font-size:11px;background:#0d2a1e;color:var(--green);border:1px solid #1c5a41}
.page{display:none}.page.active{display:block}
.card{background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:18px;overflow:hidden}
.card h3{margin:0 0 4px;font-size:15px;display:flex;align-items:center;gap:8px}
.card .hint{color:var(--muted);font-size:12px;margin:0 0 12px}
.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}
.span2{grid-column:1/-1}
canvas.chart{display:block;width:100%;border-radius:10px;cursor:crosshair}
button,.btn{background:linear-gradient(135deg,var(--accent),var(--accent2));color:#fff;border:0;border-radius:10px;
  padding:10px 18px;font-size:14px;font-weight:600;cursor:pointer;font-family:inherit}
button.ghost{background:var(--panel2);border:1px solid var(--line);color:var(--muted)}
button.ghost:hover{color:var(--text)}
button:disabled{opacity:.45;cursor:not-allowed}
.chipbar{display:flex;gap:8px;flex-wrap:wrap;margin:10px 0}
.chip{background:#12183a;border:1px solid var(--accent);color:var(--text);border-radius:20px;padding:4px 12px;font-size:12px;cursor:pointer}
.chip .x{color:var(--red);margin-left:6px;font-weight:700}
.kpis{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin-bottom:16px}
.kpi{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:14px 16px;cursor:default}
.kpi .k{color:var(--muted);font-size:11px;text-transform:uppercase;letter-spacing:.6px}
.kpi .v{font-size:26px;font-weight:700;margin-top:4px}
.kpi .s{font-size:11px;color:var(--muted)}
.kpi.green .v{color:var(--green)}.kpi.red .v{color:var(--red)}.kpi.amber .v{color:var(--amber)}.kpi.cyan .v{color:var(--cyan)}
table{width:100%;border-collapse:collapse;font-size:13px}
th{color:var(--muted);text-align:left;font-weight:600;padding:9px 10px;border-bottom:1px solid var(--line);cursor:pointer;user-select:none;white-space:nowrap}
th:hover{color:var(--text)} td{padding:9px 10px;border-bottom:1px solid #141a35}
tbody tr{cursor:pointer} tbody tr:hover{background:#10163a}
.pillsm{display:inline-block;padding:3px 10px;border-radius:14px;font-size:11px;font-weight:600}
.p-conf{background:#0d2a1e;color:var(--green);border:1px solid #1c5a41}
.p-cand{background:#2a230d;color:var(--amber);border:1px solid #5a4a1c}
.p-fp{background:#2a0d16;color:var(--red);border:1px solid #5a1c2e}
.p-anom{background:#0d1f2a;color:var(--cyan);border:1px solid #1c455a}
.search{background:var(--panel2);border:1px solid var(--line);color:var(--text);border-radius:10px;padding:9px 14px;font-size:13px;width:240px;font-family:inherit}
.search:focus{outline:none;border-color:var(--accent)}
/* upload */
.drop{border:2px dashed #2a3465;border-radius:16px;padding:46px;text-align:center;transition:.2s;cursor:pointer}
.drop.hover{border-color:var(--accent);background:#0d1230}
.drop .big{font-size:40px}
.stage{display:flex;align-items:center;gap:12px;padding:10px 0;color:var(--muted);font-size:13px}
.stage .st-ico{width:26px;height:26px;border-radius:50%;display:grid;place-items:center;background:var(--panel2);border:1px solid var(--line);font-size:12px;flex-shrink:0}
.stage.done{color:var(--text)} .stage.done .st-ico{background:#0d2a1e;border-color:#1c5a41;color:var(--green)}
.stage.run .st-ico{border-color:var(--accent);color:var(--accent)}
.stage .bar{flex:1;height:5px;border-radius:4px;background:#0a0e1e;overflow:hidden}
.stage .bar i{display:block;height:100%;width:0%;background:linear-gradient(90deg,var(--accent),var(--cyan));border-radius:4px;transition:width .25s}
/* hero + misc reused from results */
.hero{display:flex;gap:18px;align-items:center;background:linear-gradient(180deg,var(--panel),#0a0d1c);
  border:1px solid var(--line);border-radius:18px;padding:18px 22px;margin-bottom:16px;flex-wrap:wrap}
.hero h1{margin:0;font-size:22px}.hero .sub{color:var(--muted);font-size:12px;margin-top:2px}
.verdict{margin-left:auto;text-align:right}
.pill{display:inline-flex;align-items:center;gap:8px;padding:8px 16px;border-radius:30px;font-weight:700;font-size:14px}
.pill.ok{background:#0d2a1e;color:var(--green);border:1px solid #1c5a41}
.pill.bad{background:#2a0d16;color:var(--red);border:1px solid #5a1c2e}
.pill.warn{background:#2a230d;color:var(--amber);border:1px solid #5a4a1c}
.dot{width:9px;height:9px;border-radius:50%;background:currentColor;box-shadow:0 0 10px currentColor}
.conf{font-size:12px;color:var(--muted);margin-top:6px}.conf b{color:var(--text);font-size:14px}
.model{display:flex;align-items:center;gap:12px;margin:10px 0}
.model .name{width:112px;font-size:13px}
.model .track{flex:1;height:9px;background:#0a0e1e;border-radius:20px;overflow:hidden;border:1px solid var(--line)}
.model .fill{height:100%;border-radius:20px;background:linear-gradient(90deg,var(--accent),var(--cyan));transition:width .8s cubic-bezier(.2,.8,.2,1)}
.model .val{width:44px;text-align:right;font-size:13px;color:var(--muted);font-variant-numeric:tabular-nums}
.meta-row .fill{background:linear-gradient(90deg,var(--green),#7CF5C6)}.meta-row .name{font-weight:700}
.shap{display:flex;align-items:center;gap:10px;margin:8px 0;font-size:13px}
.shap .lbl{width:148px;color:var(--muted)}
.shap .barwrap{flex:1;position:relative;height:20px}
.shap .mid{position:absolute;left:50%;top:-2px;bottom:-2px;width:1px;background:var(--line)}
.shap .bar{height:14px;border-radius:4px;position:absolute;top:3px;transition:width .7s}
.shap .pos{background:var(--green);left:50%}.shap .neg{background:var(--red);right:50%}
.shap .num{width:52px;text-align:right;color:var(--text);font-variant-numeric:tabular-nums}
.params{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.param{background:var(--panel2);border:1px solid var(--line);border-radius:10px;padding:10px 13px}
.param .k{color:var(--muted);font-size:10px;text-transform:uppercase;letter-spacing:.5px}
.param .v{font-size:17px;font-weight:600;margin-top:2px}.param .v small{font-size:11px;color:var(--muted);font-weight:400}
.anom{display:flex;gap:14px;align-items:center;border-radius:12px;padding:13px;background:#0d1428;border:1px solid var(--line)}
.anom .big{font-size:26px}.anom .t{font-weight:600;font-size:13px}.anom .d{color:var(--muted);font-size:12px}
.tip{position:fixed;pointer-events:none;background:#171d3d;border:1px solid var(--accent);border-radius:9px;
  padding:8px 12px;font-size:12px;z-index:50;display:none;box-shadow:0 8px 30px #0009;line-height:1.6}
.tip b{color:var(--cyan)}
#scene3dwrap{position:relative;border-radius:12px;overflow:hidden;background:#020208}
#scene3d{display:block;width:100%;height:430px}
.s3hud{position:absolute;left:14px;bottom:12px;font-size:11px;color:#9fb0e8;background:#0a0f24cc;border:1px solid var(--line);
  border-radius:9px;padding:7px 11px;pointer-events:none}
.s3hud b{color:#fff}
.s3controls{position:absolute;right:12px;top:12px;display:flex;gap:6px}
.s3controls button{padding:6px 12px;font-size:12px;border-radius:8px}
.s3err{position:absolute;inset:0;display:none;place-items:center;text-align:center;color:var(--muted);font-size:13px;padding:30px}
footer{color:var(--muted);font-size:11px;text-align:center;margin:26px 0 8px}
.row{display:flex;align-items:center;gap:12px;flex-wrap:wrap}
.mut{color:var(--muted)} .right{margin-left:auto}
@media(max-width:900px){.grid{grid-template-columns:1fr}.kpis{grid-template-columns:repeat(2,1fr)}}
</style>
</head>
