<script>
/* ============ tiny helpers ============ */
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const tip=$('#tip');
function showTip(x,y,html){tip.style.display='block';tip.innerHTML=html;
  const r=tip.getBoundingClientRect();
  tip.style.left=Math.min(x+14,innerWidth-r.width-10)+'px';
  tip.style.top=Math.min(y+14,innerHeight-r.height-10)+'px';}
function hideTip(){tip.style.display='none'}
function fmt(n,d=2){return Number(n).toFixed(d)}

/* ============ seeded RNG so the demo data is stable ============ */
let _seed=42;function rnd(){_seed=(_seed*1103515245+12345)&0x7fffffff;return _seed/0x7fffffff}

/* ============ DATA STORE — localStorage stands in for Supabase ============ */
const DISPS=['CONFIRMED','CANDIDATE','FALSE POSITIVE','ANOMALY'];
function makeSeed(){
  const names=[['Kepler-90 i','KIC 11442793',14.45,203,18.7,.963,'CONFIRMED'],
    ['Kepler-10 b','KIC 11904151',0.84,152,32.1,.988,'CONFIRMED'],
    ['Kepler-8 b','KIC 6922244',3.52,9100,45.3,.991,'CONFIRMED'],
    ['KOI-4427.01','KIC 4172805',147.66,410,9.2,.71,'CANDIDATE'],
    ['KOI-5123.01','KIC 5651104',22.34,310,7.8,.64,'CANDIDATE'],
    ['KIC 4862625','binary A',5.56,14800,51.0,.08,'FALSE POSITIVE'],
    ['KIC 9832227','contact binary',0.46,22000,63.2,.03,'FALSE POSITIVE'],
    ['KIC 8462852','Boyajian dips',700,2200,12.1,.41,'ANOMALY'],
    ['KOI-6705.01','KIC 6705',41.03,95,5.9,.55,'CANDIDATE']];
  const rows=names.map((n,i)=>({id:'c'+i,name:n[0],kic:n[1],period:n[2],depth:n[3],snr:n[4],conf:n[5],disp:n[6],
    dur:+fmt(1.5+rnd()*6,1),rp:+fmt(.8+rnd()*3,2),oddEven:+fmt(rnd()*3,1),recon:n[6]==='ANOMALY'?.21:.01+rnd()*.05}));
  for(let i=rows.length;i<34;i++){
    const disp=DISPS[rnd()<.38?0:rnd()<.55?1:rnd()<.8?2:3];
    const conf=disp==='CONFIRMED'?.85+rnd()*.14:disp==='CANDIDATE'?.5+rnd()*.3:disp==='FALSE POSITIVE'?rnd()*.25:.3+rnd()*.3;
    rows.push({id:'c'+i,name:'KOI-'+(1000+Math.floor(rnd()*8000))+'.01',kic:'KIC '+(3000000+Math.floor(rnd()*9000000)),
      period:+fmt(.5+rnd()*rnd()*120,2),depth:Math.round(60+rnd()*rnd()*20000),snr:+fmt(4+rnd()*60,1),
      conf:+fmt(conf,3),disp,dur:+fmt(1+rnd()*8,1),rp:+fmt(.5+rnd()*4,2),oddEven:+fmt(rnd()*(disp==='FALSE POSITIVE'?25:3),1),
      recon:+(disp==='ANOMALY'?.12+rnd()*.2:.005+rnd()*.06).toFixed(3)});
  }
  return rows;
}
let DB=JSON.parse(localStorage.getItem('exodetect_db')||'null');
if(!DB){DB=makeSeed();localStorage.setItem('exodetect_db',JSON.stringify(DB));}
function saveDB(){localStorage.setItem('exodetect_db',JSON.stringify(DB));updateBadge();}
function updateBadge(){$('#dbBadge').textContent='● local store: '+DB.length+' candidates';}
updateBadge();

/* ============ ROUTER ============ */
$$('.nav a').forEach(a=>a.onclick=()=>{
  $$('.nav a').forEach(x=>x.classList.remove('active'));a.classList.add('active');
  $$('.page').forEach(p=>p.classList.remove('active'));
  $('#page-'+a.dataset.page).classList.add('active');
  if(a.dataset.page==='browse')renderBrowse();
  if(a.dataset.page==='anomalies')renderAnoms();
  if(a.dataset.page==='results'){resize3d();drawLC();}
});
function goto(page){$$('.nav a').forEach(x=>x.classList.toggle('active',x.dataset.page===page));
  $$('.page').forEach(p=>p.classList.remove('active'));$('#page-'+page).classList.add('active');}

/* ============ STARFIELD ============ */
(function(){const c=$('#stars'),x=c.getContext('2d');
function size(){c.width=innerWidth;c.height=innerHeight}size();addEventListener('resize',size);
const st=Array.from({length:150},()=>({x:Math.random(),y:Math.random(),r:Math.random()*1.3+.2,tw:Math.random()*6}));
(function loop(t){x.clearRect(0,0,c.width,c.height);
for(const s of st){x.globalAlpha=.35+.55*Math.abs(Math.sin(t/900+s.tw));x.fillStyle='#cdd8ff';
x.beginPath();x.arc(s.x*c.width,s.y*c.height,s.r,0,7);x.fill()}requestAnimationFrame(loop)})(0)})();

/* ============ CURRENT CANDIDATE (results page) ============ */
let CUR=DB[0];
function lcParams(c){ // synth curve params derived from candidate values
  return {per:Math.max(20,Math.min(200,c.period*8)),depth:Math.max(.002,Math.min(.05,c.depth/2e5)),
    dur:Math.max(6,Math.min(26,c.dur*3)),noise:c.disp==='FALSE POSITIVE'?.004:.0022,
    vshape:c.disp==='FALSE POSITIVE',weird:c.disp==='ANOMALY'};}
function renderResults(c){
  CUR=c;
  $('#rTitle').innerHTML=c.name+' <span class="mut" style="font-size:14px">· '+c.kic+'</span>';
  $('#rSub').textContent='Kepler mission · '+(40000+Math.floor(c.snr*900)).toLocaleString()+' cadences · analysed in '+fmt(1+c.snr/30,1)+'s';
  const pill=$('#rPill'),conf=$('#rConf');
  const isP=c.disp==='CONFIRMED'||c.disp==='CANDIDATE';
  pill.className='pill '+(c.disp==='CONFIRMED'?'ok':c.disp==='CANDIDATE'?'warn':c.disp==='ANOMALY'?'warn':'bad');
  pill.innerHTML='<span class="dot"></span> '+(c.disp==='CONFIRMED'?'PLANET DETECTED':c.disp==='CANDIDATE'?'PLANET CANDIDATE':c.disp==='ANOMALY'?'NOVEL SIGNAL — REVIEW':'FALSE POSITIVE');
  conf.innerHTML='ensemble confidence <b>'+fmt(c.conf*100,1)+'%</b> · FP prob <b>'+fmt((1-c.conf)*88,1)+'%</b>';
  $('#rParams').innerHTML=
    par('Orbital period',fmt(c.period,2),'days')+par('Planet radius',fmt(c.rp,2),'R⊕')+
    par('Transit depth',c.depth.toLocaleString(),'ppm')+par('Duration',fmt(c.dur,1),'hrs')+
    par('Signal-to-noise',fmt(c.snr,1),'σ')+par('Odd–even Δ',fmt(c.oddEven,1),'% '+(c.oddEven<5?'✓ low':'⚠ high'));
  const m={cnn:.5+c.conf*.49,lstm:.45+c.conf*.5,tr:.48+c.conf*.49,xgb:.42+c.conf*.52,fp:1-c.conf*.96};
  if(!isP){m.cnn=c.conf*.9+.03;m.lstm=c.conf*.8+.05;m.tr=c.conf*.85+.04;m.xgb=c.conf*.75+.06;m.fp=.92-c.conf*.5}
  $('#rModels').innerHTML=
    bar('1D CNN',m.cnn)+bar('LSTM',m.lstm)+bar('Transformer',m.tr)+bar('XGBoost',m.xgb)+bar('FP Specialist',m.fp)+
    '<div style="height:1px;background:var(--line);margin:12px 0"></div>'+bar('Meta-learner',c.conf,true);
  const s=[['Transit SNR',.31*(isP?1:-1)],['Odd–even match',(c.oddEven<5?.24:-.28)],
    ['Transit symmetry',isP?.18:-.14],['Period stability',.11],['Secondary eclipse',c.disp==='FALSE POSITIVE'?-.31:-.08]];
  $('#rShap').innerHTML=s.map(([l,v])=>shapRow(l,v)).join('');
  const an=$('#rAnom');
  if(c.disp==='ANOMALY'){an.style.borderColor='#5a4a1c';
    an.innerHTML='<div class="big">🚨</div><div><div class="t" style="color:var(--amber)">NOVELTY FLAG — routed to human review</div><div class="d">Reconstruction error '+fmt(c.recon,3)+' (threshold 0.100). Morphology does not match learned transit shapes — possible TTV / circumbinary / multi-planet signal.</div></div>';}
  else{an.style.borderColor='#1c5a41';
    an.innerHTML='<div class="big">✅</div><div><div class="t">Nominal — no novelty flag</div><div class="d">Reconstruction error '+fmt(c.recon,3)+' (threshold 0.100). Signal matches known morphology; not routed to review queue.</div></div>';}
  buildSeries();drawLC();set3dFromCandidate();
}
const par=(k,v,s)=>'<div class="param"><div class="k">'+k+'</div><div class="v">'+v+' <small>'+s+'</small></div></div>';
