/* ============ LIGHT CURVE — interactive (hover tooltip, drag-zoom, dbl-reset) ============ */
let lcView='clean', SERIES={};
function buildSeries(){
  const p=lcParams(CUR), N=1100;_seed=99;
  const mk=mode=>{const ys=[];for(let i=0;i<N;i++){let f=1;
    if(mode!=='fold'){
      if(mode==='raw')f+=Math.sin(i/70)*.006+Math.sin(i/23)*.003;
      const ph=((i%p.per)+p.per)%p.per,d=Math.abs(ph-p.per/2);
      if(d<p.dur/2){const t=(ph-p.per/2)/(p.dur/2);
        f-=p.depth*(p.vshape?1-Math.abs(t)*.55:1-t*t);
        if(p.weird&&Math.floor(i/p.per)%3===1)f+=p.depth*.5;}
      if(p.vshape){const ph2=((i+p.per/2)%p.per);if(Math.abs(ph2-p.per/2)<p.dur/2)f-=p.depth*.45}
      f+=(rnd()-.5)*(mode==='raw'?.006:p.noise);
    }else{const ph=(i/N)*p.per,d=Math.abs(ph-p.per/2);
      if(d<p.dur/2){const t=(ph-p.per/2)/(p.dur/2);f-=p.depth*(p.vshape?1-Math.abs(t)*.55:1-t*t)}
