  lcX.strokeStyle='rgba(102,132,255,.3)';lcX.setLineDash([4,4]);lcX.beginPath();lcX.moveTo(padL,Y(1));lcX.lineTo(W-padR,Y(1));lcX.stroke();lcX.setLineDash([]);
  const grad=lcX.createLinearGradient(0,0,W,0);grad.addColorStop(0,'#4de3ff');grad.addColorStop(1,'#8b5cff');
  if(lcView==='fold'){lcX.fillStyle='#9fb0e8';
