  else{lcX.strokeStyle=grad;lcX.lineWidth=1.5;lcX.shadowColor='rgba(77,227,255,.55)';lcX.shadowBlur=8;
    lcX.beginPath();for(let i=i0;i<i1;i++){const px=X(i),py=Y(ys[i]);i===i0?lcX.moveTo(px,py):lcX.lineTo(px,py)}
    lcX.stroke();lcX.shadowBlur=0}
  if(lcDrag&&lcDrag.x2){lcX.fillStyle='rgba(77,227,255,.12)';lcX.strokeStyle='#4de3ff';
    lcX.fillRect(lcDrag.x1,padT,lcDrag.x2-lcDrag.x1,H-padT-padB);lcX.strokeRect(lcDrag.x1,padT,lcDrag.x2-lcDrag.x1,H-padT-padB)}
  lcX.fillStyle='#8e97c2';lcX.fillText(lcView==='fold'?'orbital phase':'time (days)',W/2-28,H-8);
  if(lcZoom[0]>0||lcZoom[1]<1){lcX.fillStyle='#4de3ff';lcX.fillText('zoomed '+fmt(lcZoom[0]*100,0)+'–'+fmt(lcZoom[1]*100,0)+'% · double-click to reset',W-235,padT+4)}
  lcC._map={X,Y,i0,i1,ys,padL,padR,W};
