});
lcC.addEventListener('mouseleave',hideTip);
lcC.addEventListener('mousedown',e=>{const r=lcC.getBoundingClientRect();lcDrag={x1:e.clientX-r.left,x2:null}});
addEventListener('mouseup',()=>{if(lcDrag&&lcDrag.x2!==null){const m=lcC._map,W=m.W;
  let[a,b]=[lcDrag.x1,lcDrag.x2].sort((p,q)=>p-q);
  if(b-a>12){const f1=(a-m.padL)/(W-m.padL-m.padR),f2=(b-m.padL)/(W-m.padL-m.padR);
    const span=lcZoom[1]-lcZoom[0];
    lcZoom=[Math.max(0,lcZoom[0]+f1*span),Math.min(1,lcZoom[0]+f2*span)]}}
