/* ============ browse dashboard (cross-filtering) ============ */
const F={disp:null,band:null,box:null,q:''};
let sortK='conf',sortDir=-1;
function filtered(){
  return DB.filter(c=>
    (!F.disp||c.disp===F.disp)&&
    (!F.band||(c.conf>=F.band[0]&&c.conf<F.band[1]))&&
    (!F.box||(c.period>=F.box.p0&&c.period<=F.box.p1&&c.depth>=F.box.d0&&c.depth<=F.box.d1))&&
    (!F.q||(c.name+' '+c.kic).toLowerCase().includes(F.q)));
}
function renderChips(){
  const el=$('#filterChips');el.innerHTML='';
  const mk=(t,clear)=>{const d=document.createElement('div');d.className='chip';
    d.innerHTML=t+'<span class="x">✕</span>';d.onclick=()=>{clear();renderBrowse()};el.appendChild(d)};
  if(F.disp)mk('disposition: '+F.disp,()=>F.disp=null);
  if(F.band)mk('confidence '+fmt(F.band[0]*100,0)+'–'+fmt(F.band[1]*100,0)+'%',()=>F.band=null);
  if(F.box)mk('scatter box',()=>F.box=null);
}
function renderBrowse(){
  renderChips();
  const rows=filtered();
  const nC=rows.filter(c=>c.disp==='CONFIRMED').length,nCa=rows.filter(c=>c.disp==='CANDIDATE').length,
        nF=rows.filter(c=>c.disp==='FALSE POSITIVE').length,nA=rows.filter(c=>c.disp==='ANOMALY').length;
  $('#kpis').innerHTML=
    kpi('Total candidates',rows.length,'in current filter','')+
    kpi('Confirmed',nC,'planet detections','green')+
    kpi('Candidates',nCa,'need follow-up','amber')+
    kpi('False positives',nF,'binaries & noise','red')+
    kpi('Anomalies',nA,'novelty queue','cyan');
  drawDonut(rows);drawHist(rows);drawScatter(rows);renderTable(rows);
}
const kpi=(k,v,s,cls)=>'<div class="kpi '+cls+'"><div class="k">'+k+'</div><div class="v">'+v+'</div><div class="s">'+s+'</div></div>';
const DCOL={CONFIRMED:'#34f5b0',CANDIDATE:'#ffc24d','FALSE POSITIVE':'#ff5c7a',ANOMALY:'#4de3ff'};
function drawDonut(rows){
  const c=$('#donut'),x=c.getContext('2d'),W=c.clientWidth||500,H=220;
  c.width=W*devicePixelRatio;c.height=H*devicePixelRatio;x.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);
  x.clearRect(0,0,W,H);
  const counts=DISPS.map(d=>DB.filter(r=>r.disp===d).length),tot=DB.length;
  const cx=W*.3,cy=H/2,R=78,r2=46;let a0=-Math.PI/2;c._arcs=[];
  DISPS.forEach((d,i)=>{const frac=counts[i]/tot,a1=a0+frac*Math.PI*2;
    const sel=!F.disp||F.disp===d;
    x.beginPath();x.moveTo(cx,cy);x.arc(cx,cy,R+(F.disp===d?6:0),a0,a1);x.closePath();
    x.fillStyle=DCOL[d];x.globalAlpha=sel?1:.22;
    x.shadowColor=DCOL[d];x.shadowBlur=sel&&F.disp===d?18:0;x.fill();x.shadowBlur=0;x.globalAlpha=1;
    c._arcs.push({a0,a1,d});a0=a1});
  x.globalCompositeOperation='destination-out';x.beginPath();x.arc(cx,cy,r2,0,7);x.fill();
  x.globalCompositeOperation='source-over';
  x.fillStyle='#eaf0ff';x.font='800 22px Orbitron';x.textAlign='center';
  x.fillText(rows.length,cx,cy+2);x.font='10px Space Grotesk';x.fillStyle='#8e97c2';x.fillText('shown',cx,cy+17);x.textAlign='left';
  x.font='12px Space Grotesk';
  DISPS.forEach((d,i)=>{const y=40+i*26;x.fillStyle=DCOL[d];x.fillRect(W*.58,y-9,10,10);
    x.fillStyle=F.disp&&F.disp!==d?'#5a6288':'#eaf0ff';x.fillText(d.toLowerCase()+' — '+counts[i],W*.58+18,y)});
  c.onclick=e=>{const r=c.getBoundingClientRect(),mx=e.clientX-r.left,my=e.clientY-r.top;
    const dx=mx-cx,dy=my-cy,dist=Math.hypot(dx,dy);
    if(dist>r2&&dist<R+8){let ang=Math.atan2(dy,dx);if(ang<-Math.PI/2)ang+=Math.PI*2;
      const hit=c._arcs.find(a=>ang>=a.a0&&ang<a.a1);
      if(hit){F.disp=F.disp===hit.d?null:hit.d;renderBrowse()}}
    else if(mx>W*.55){const i=Math.floor((my-30)/26);if(DISPS[i]){F.disp=F.disp===DISPS[i]?null:DISPS[i];renderBrowse()}}};
  c.onmousemove=e=>{const r=c.getBoundingClientRect(),dx=e.clientX-r.left-cx,dy=e.clientY-r.top-cy,dist=Math.hypot(dx,dy);
    if(dist>r2&&dist<R+8){let ang=Math.atan2(dy,dx);if(ang<-Math.PI/2)ang+=Math.PI*2;
      const hit=c._arcs.find(a=>ang>=a.a0&&ang<a.a1);
      if(hit){const n=DB.filter(q=>q.disp===hit.d).length;
        showTip(e.clientX,e.clientY,'<b>'+hit.d+'</b><br>'+n+' of '+DB.length+' ('+fmt(n/DB.length*100,0)+'%)<br><span class="mut">click to cross-filter</span>');return}}
    hideTip()};
  c.onmouseleave=hideTip;
}
function drawHist(rows){
  const c=$('#hist'),x=c.getContext('2d'),W=c.clientWidth||500,H=220;
  c.width=W*devicePixelRatio;c.height=H*devicePixelRatio;x.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);
  x.clearRect(0,0,W,H);
  const bins=10,all=new Array(bins).fill(0),cur=new Array(bins).fill(0);
  DB.forEach(r=>all[Math.min(bins-1,Math.floor(r.conf*bins))]++);
  rows.forEach(r=>cur[Math.min(bins-1,Math.floor(r.conf*bins))]++);
  const mx=Math.max(...all,1),padL=30,padB=26,bw=(W-padL-14)/bins;
  c._bars=[];
  for(let i=0;i<bins;i++){
    const h1=(H-padB-16)*all[i]/mx,h2=(H-padB-16)*cur[i]/mx;
    const bx=padL+i*bw,sel=F.band&&F.band[0]===i/bins;
    x.fillStyle='rgba(102,132,255,.1)';x.fillRect(bx+2,H-padB-h1,bw-4,h1);
    const g=x.createLinearGradient(0,H-padB-h2,0,H-padB);g.addColorStop(0,sel?'#4de3ff':'#6c8bff');g.addColorStop(1,'rgba(40,60,140,.5)');
    x.fillStyle=g;if(sel){x.shadowColor='#4de3ff';x.shadowBlur=14}x.fillRect(bx+2,H-padB-h2,bw-4,h2);x.shadowBlur=0;
    c._bars.push({bx,bw,i,n:cur[i],na:all[i]});
    x.fillStyle='#8e97c2';x.font='10px Space Grotesk';if(i%2===0)x.fillText(i*10+'%',bx+2,H-8)}
  c.onclick=e=>{const r=c.getBoundingClientRect(),mx2=e.clientX-r.left;
    const b=c._bars.find(b=>mx2>=b.bx&&mx2<b.bx+b.bw);
    if(b){const band=[b.i/bins,(b.i+1)/bins];F.band=(F.band&&F.band[0]===band[0])?null:band;renderBrowse()}};
  c.onmousemove=e=>{const r=c.getBoundingClientRect(),mx2=e.clientX-r.left;
    const b=c._bars.find(b=>mx2>=b.bx&&mx2<b.bx+b.bw);
    if(b)showTip(e.clientX,e.clientY,'<b>'+(b.i*10)+'–'+(b.i*10+10)+'% confidence</b><br>'+b.n+' shown / '+b.na+' total<br><span class="mut">click to filter this band</span>');else hideTip()};
  c.onmouseleave=hideTip;
}
let scDrag=null;
function drawScatter(rows){
  const c=$('#scatter'),x=c.getContext('2d'),W=c.clientWidth||900,H=260;
  c.width=W*devicePixelRatio;c.height=H*devicePixelRatio;x.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);
  x.clearRect(0,0,W,H);
  const padL=56,padR=16,padT=12,padB=30;
  const pmin=.3,pmax=200,dmin=40,dmax=25000;
  const X=p=>padL+(W-padL-padR)*(Math.log10(p)-Math.log10(pmin))/(Math.log10(pmax)-Math.log10(pmin));
  const Y=d=>padT+(H-padT-padB)*(1-(Math.log10(d)-Math.log10(dmin))/(Math.log10(dmax)-Math.log10(dmin)));
  x.strokeStyle='rgba(102,132,255,.14)';x.fillStyle='#8e97c2';x.font='10px Space Grotesk';
  [1,10,100].forEach(p=>{x.beginPath();x.moveTo(X(p),padT);x.lineTo(X(p),H-padB);x.stroke();x.fillText(p+'d',X(p)+3,H-padB+14)});
  [100,1000,10000].forEach(d=>{x.beginPath();x.moveTo(padL,Y(d));x.lineTo(W-padR,Y(d));x.stroke();x.fillText(d.toLocaleString()+'ppm',4,Y(d)+3)});
  x.fillText('orbital period (log)',W/2-30,H-6);
  c._pts=[];
  DB.forEach(r=>{const inSet=rows.includes(r);
    const px=X(Math.max(pmin,Math.min(pmax,r.period))),py=Y(Math.max(dmin,Math.min(dmax,r.depth)));
    const rad=3+Math.min(7,r.snr/9);
    x.beginPath();x.arc(px,py,rad,0,7);x.fillStyle=DCOL[r.disp];x.globalAlpha=inSet?.95:.12;
    if(inSet){x.shadowColor=DCOL[r.disp];x.shadowBlur=9}x.fill();x.shadowBlur=0;
    if(r.id===CUR.id&&inSet){x.strokeStyle='#fff';x.lineWidth=1.5;x.stroke()}
    x.globalAlpha=1;c._pts.push({px,py,rad,r})});
  if(scDrag&&scDrag.x2!==null){x.fillStyle='rgba(77,227,255,.1)';x.strokeStyle='#4de3ff';
    x.fillRect(scDrag.x1,scDrag.y1,scDrag.x2-scDrag.x1,scDrag.y2-scDrag.y1);
    x.strokeRect(scDrag.x1,scDrag.y1,scDrag.x2-scDrag.x1,scDrag.y2-scDrag.y1)}
  c._inv={X,Y,pmin,pmax,dmin,dmax,padL,padR,padT,padB,W,H};
}
$('#scatter').addEventListener('mousemove',e=>{
  const c=$('#scatter'),r=c.getBoundingClientRect(),mx=e.clientX-r.left,my=e.clientY-r.top;
  if(scDrag){scDrag.x2=mx;scDrag.y2=my;drawScatter(filtered());return}
  const hit=(c._pts||[]).findLast(p=>Math.hypot(mx-p.px,my-p.py)<p.rad+3);
  if(hit){showTip(e.clientX,e.clientY,'<b>'+hit.r.name+'</b><br>period '+hit.r.period+'d · depth '+hit.r.depth.toLocaleString()+'ppm<br>SNR '+hit.r.snr+' · conf '+fmt(hit.r.conf*100,0)+'%<br><span class="mut">'+hit.r.disp.toLowerCase()+' · click to open</span>');c.style.cursor='pointer'}
  else{hideTip();c.style.cursor='crosshair'}});
$('#scatter').addEventListener('mousedown',e=>{const r=$('#scatter').getBoundingClientRect();
  scDrag={x1:e.clientX-r.left,y1:e.clientY-r.top,x2:null,y2:null}});
addEventListener('mouseup',e=>{const c=$('#scatter');if(!scDrag)return;
  const wasClick=scDrag.x2===null||Math.hypot(scDrag.x2-scDrag.x1,scDrag.y2-scDrag.y1)<8;
  if(wasClick){const r=c.getBoundingClientRect(),mx=e.clientX-r.left,my=e.clientY-r.top;
    const hit=(c._pts||[]).findLast(p=>Math.hypot(mx-p.px,my-p.py)<p.rad+3);
    if(hit){renderResults(hit.r);goto('results');hideTip()}}
  else{const v=c._inv,[a,b]=[scDrag.x1,scDrag.x2].sort((p,q)=>p-q),[y1,y2]=[scDrag.y1,scDrag.y2].sort((p,q)=>p-q);
    const unX=px=>Math.pow(10,Math.log10(v.pmin)+(px-v.padL)/(v.W-v.padL-v.padR)*(Math.log10(v.pmax)-Math.log10(v.pmin)));
    const unY=py=>Math.pow(10,Math.log10(v.dmin)+(1-(py-v.padT)/(v.H-v.padT-v.padB))*(Math.log10(v.dmax)-Math.log10(v.dmin)));
    F.box={p0:unX(a),p1:unX(b),d0:unY(y2),d1:unY(y1)};renderBrowse()}
  scDrag=null});
function renderTable(rows){
