let running=false;
function ingest(fname,kind){
  if(running)return;running=true;
  const stages=$$('#stages .stage'),msgs=[
    'removing bad-quality cadences, NaN gaps, cosmic-ray hits…',
    'Savitzky–Golay detrend (window > transit duration) + normalize…',
    'Box Least Squares: scanning 12,000 trial periods…',
    'extracting depth, duration, odd–even, secondary, symmetry…',
    'CNN + LSTM + Transformer + XGBoost + FP-specialist → meta-learner…'];
  stages.forEach(s=>{s.className='stage';s.querySelector('.bar i').style.width='0%';s.querySelector('.pct').textContent='–';s.querySelector('.st-ico').textContent=+s.dataset.s+1});
  $('#pipeMsg').textContent='📥 '+fname+' received — starting pipeline';
  let si=0;
  function runStage(){
    if(si>=stages.length){finish();return}
    const st=stages[si];st.classList.add('run');$('#pipeMsg').textContent='⚙️ '+msgs[si];
    let p=0;const iv=setInterval(()=>{
      p+=8+Math.random()*18;if(p>=100){p=100;clearInterval(iv);st.classList.remove('run');st.classList.add('done');
        st.querySelector('.st-ico').textContent='✓';si++;setTimeout(runStage,120)}
      st.querySelector('.bar i').style.width=p+'%';st.querySelector('.pct').textContent=Math.floor(p)+'%';
    },90)}
  function finish(){
    running=false;$('#pipeMsg').textContent='✅ pipeline complete — stored to local DB, opening results';
    const isFP=kind==='fp'||/binary|4862625/i.test(fname);
    _seed=Date.now()&0xffff;
    const c={id:'u'+Date.now(),name:fname.replace(/\.(fits|csv|txt)$/i,'').replace(/_/g,' '),kic:'uploaded',
