    return {x:Math.cos(a)*(ORBIT_R+(R2[i]-.5)*1.6), y:(R3[i]-.5)*.9, z:Math.sin(a)*(ORBIT_R+(R4[i]-.5)*1.6),
            r:.25*glow, g:.7*glow, b:1.4*glow, s:.9+glow};
  }                                             // -- deep starfield sphere
  const rr=70+R1[i]*120, th=R2[i]*6.283, ph=Math.acos(2*R3[i]-1);
  const c=.25+R4[i]*.75, blue=R2[i]<.3;
  return {x:rr*Math.sin(ph)*Math.cos(th), y:rr*Math.sin(ph)*Math.sin(th), z:rr*Math.cos(ph),
          r:c*(blue?.6:1), g:c*(blue?.8:.95), b:c*1.1, s:.6+R3[i]*1.2};
}

function fCurve(i,P){                            // -- Scene B: folded light-curve 3D terrain
  const COLS=340, ROWS=Math.floor(COUNT/COLS);
  const row=Math.floor(i/COLS), col=i%COLS;
  if(row>=ROWS)return {x:0,y:-500,z:0,r:0,g:0,b:0,s:0};
  const phx=col/COLS-.5;                         // phase -0.5..0.5
  const durP=.09, t=phx/durP;
  let y=0;
  if(Math.abs(phx)<durP){const v=P.disp==='FALSE POSITIVE'?1-Math.abs(t)*.55:1-t*t;
    y=-P.depth*26*Math.max(0,v)}
  if(P.disp==='ANOMALY'&&row%7===3&&Math.abs(phx)<durP)y*=.35;
  y+=(R1[i]-.5)*1.1;                             // per-orbit noise
  const deep=Math.min(1,-y/14);
  return {x:phx*95, y:y+6, z:(row/ROWS-.5)*58,
          r:.2+deep*1.4, g:.55+deep*.5, b:1.3-deep*.15, s:.9+deep*1.8};
}

function fGalaxy(i){                             // -- reference's spiral, recolored violet/cyan
  if(i<COUNT*0.12){
    const rr=Math.pow(R1[i],1.6)*9, th=R2[i]*6.283, ph=Math.acos(2*R3[i]-1);
    return {x:rr*Math.sin(ph)*Math.cos(th), y:rr*Math.sin(ph)*Math.sin(th)*.55, z:rr*Math.cos(ph),
            r:1.5, g:1.2, b:1.7, s:2.2};
  }
  const arms=3, t=i/COUNT;
  const a=t*15+((i%arms)*(6.283/arms));
  const rad=2+t*46;
  const swirl=R4[i]*.35;
  return {x:rad*Math.cos(a+swirl), y:(R1[i]-.5)*(9*t), z:rad*Math.sin(a+swirl),
          r:.35+t*.5, g:.25+t*.35, b:1.1, s:.8+R2[i]*1.4};
}

/* ---------- write targets for the active formation ---------- */
function computeTargets(full){
  const S=window.__s3, P=S.params||{rp:1.3,period:14,depth:.3,disp:'CONFIRMED'};
  const planetR=Math.min(4,1.1+P.rp*.6);
  const f=S.formation;
  for(let i=0;i<COUNT;i++){
    // in system mode, only dynamic zones (star dim, planet, ring) need per-frame updates
    if(!full && f==='system'){const u=i/COUNT; if(u>=0.48) continue;}
    else if(!full && f!=='system') break;
    const p= f==='curve'?fCurve(i,P) : f==='galaxy'?fGalaxy(i) : fSystem(i,P,planetR);
    targetPos[i*3]=p.x;targetPos[i*3+1]=p.y;targetPos[i*3+2]=p.z;
    targetCol[i*3]=p.r;targetCol[i*3+1]=p.g;targetCol[i*3+2]=p.b;
    targetSize[i]=p.s;
  }
}
computeTargets(true);
positions.set(targetPos);colors.set(targetCol);sizes.set(targetSize);   // start formed

/* ---------- animate: lerp morph (the reference's signature move) ---------- */
const hudPhase=document.getElementById('s3phase'),hud=document.getElementById('s3hud');
let lastForm=window.__s3.formation;
function animate(t){
  requestAnimationFrame(animate);
  const S=window.__s3, P=S.params||{rp:1.3,period:14,depth:.3,disp:'CONFIRMED'};
  const planetR=Math.min(4,1.1+P.rp*.6);
  /* orbital motion + smooth transit physics (observer on +Z axis) */
  angle+=(.6/Math.sqrt(Math.max(.5,P.period)))*.016;
  const px=Math.cos(angle)*ORBIT_R, pz=Math.sin(angle)*ORBIT_R;
  const ov=Math.max(0,Math.min(1,(STAR_R+planetR-Math.abs(px))/(2*planetR)));
  const transiting=pz>0&&ov>0.02&&S.formation==='system';
