  const k=.075;
  for(let i=0;i<COUNT*3;i++){positions[i]+=(targetPos[i]-positions[i])*k;
    colors[i]+=(targetCol[i]-colors[i])*k}
  for(let i=0;i<COUNT;i++)sizes[i]+=(targetSize[i]-sizes[i])*k;
  geometry.attributes.position.needsUpdate=true;
  geometry.attributes.color.needsUpdate=true;
